# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "Internal::V1::Timekeeping::EntrySnapshots", type: :request do
  # "A request with no credential, a wrong one or a user token gets 401 or 403 and writes nothing."
  it "refuses a valid higher-version batch sent with a user token and leaves the stored and new rows untouched" do
    company = create(:company)
    user = create(:user)
    create(:employment, company:, user:)
    user.add_role(:owner, company)
    project = create(:project, client: create(:client, company:))
    stored = create(:timesheet_entry, user:, project:, note: "stored note")
    stored.update_columns(version: 1, company_id: company.id)
    new_id = TimesheetEntry.maximum(:id).to_i + 1000

    entry = lambda do |id, version|
      {
        "id" => id, "company_id" => company.id, "version" => version, "project_id" => project.id,
        "user_id" => user.id, "agent_id" => nil, "work_date" => "2026-03-02", "duration" => 90.0,
        "note" => "v#{version}", "bill_status" => "unbilled", "review_status" => "not_required",
        "locked" => false, "source" => "manual", "source_metadata" => {}, "external_run_id" => nil,
        "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {}, "discarded_at" => nil,
        "created_at" => "2026-03-02T09:00:00Z", "updated_at" => "2026-03-02T09:00:00Z"
      }
    end
    body = {
      "schema_version" => 1,
      "snapshots" => [
        { "generation" => TimekeepingOwnership.current.generation, "outbox_position" => 1, "entry" => entry.call(stored.id, 5) },
        { "generation" => TimekeepingOwnership.current.generation, "outbox_position" => 2, "entry" => entry.call(new_id, 1) }
      ]
    }
    user_token = Timekeeping::UserToken.mint(user:, company:, private_key: timekeeping_key_pair)
    expect(stored.reload.attributes.slice("version", "note")).to eq("version" => 1, "note" => "stored note")

    with_timekeeping_service_token do
      post "/internal/v1/timekeeping/entry-snapshots", params: body.to_json,
        headers: { "Authorization" => "Bearer #{user_token}", "Content-Type" => "application/json",
                   "Idempotency-Key" => SecureRandom.uuid }
    end

    expect([401, 403]).to include(response.status)
    expect(stored.reload.attributes.slice("version", "note")).to eq("version" => 1, "note" => "stored note")
    expect(TimesheetEntry.unscoped.where(id: new_id)).not_to exist
  end
end
